-- ============================================================================
--  SivaComm - complete database script for PostgreSQL 16+. GENERATED by
--  deploy\New-SchemaScripts.ps1 - do not edit by hand.
--
--  Takes a blank server to a ready database in one run, as the superuser:
--
--      psql -U postgres -v app_password='<choose one>' -f full-schema.sql
--
--  1. role, database, schema comm, privileges  (= 01-create-database.sql)
--  2. SET ROLE to the application role, then every table, index and
--     constraint, and the __EFMigrationsHistory rows  (= migrate.sql)
--
--  Safe to re-run. No data is inserted: applications, keys and templates come
--  from the Applications section of appsettings.Production.json when the
--  service starts, and the first dashboard admin from its Admin section.
-- ============================================================================
-- SivaComm: the one-time server setup — the application's role, its
-- database, its schema and every privilege it needs. Run as the postgres
-- superuser:
--
--     psql -U postgres -v app_password='<choose one>' -f 01-create-database.sql
--
-- Variables:
--
--   app_password  the role's password — REQUIRED for a server. The same value
--                 goes into Database:Password in appsettings.Production.json.
--   app_user      the login the application signs in as.   default sivacomm
--   db_name       the database it owns.                     default sivacomm
--   developer     set to anything for a developer machine: grants CREATEDB
--                 (the tests make a throwaway database each) and allows the
--                 password to default to sivacomm-dev. A server role never
--                 gets CREATEDB.
--
-- After this the database is empty. The tables come from either
--   * the installer (Install-SivaComm.ps1 runs SivaComm.Api.exe --migrate), or
--   * full-schema.sql / migrate.sql in the same folder, for a DBA who wants to
--     read and run the SQL themselves.
-- Both can be used, in either order: each skips what is already applied.
--
-- Safe to re-run: an existing role gets the password given, an existing
-- database and schema are kept, and the grants are re-applied.
--
-- The role OWNS the database and the comm schema. That is what lets the
-- application's migrations create and alter tables later, as this same role,
-- with no superuser involved after this script.
--
-- Each statement is a SELECT that produces the DDL and \gexec that runs it:
-- psql substitutes :'variables' in a query but not inside a $$ block, and
-- CREATE DATABASE refuses to run inside one anyway. format()'s %I quotes an
-- identifier and %L a literal, so a password needing quotes is escaped
-- rather than breaking the statement.

\set ON_ERROR_STOP on

\if :{?app_user}
\else
    \set app_user 'sivacomm'
\endif

\if :{?db_name}
\else
    \set db_name 'sivacomm'
\endif

\if :{?app_password}
\else
    \if :{?developer}
        \set app_password 'sivacomm-dev'
    \else
        -- An error, not \quit: \quit exits 0 and a calling script would carry on.
        DO $$ BEGIN RAISE EXCEPTION 'app_password is required: psql -U postgres -v app_password=''<choose one>'' -f <this file>'; END $$;
    \endif
\endif

\echo Role :app_user, database :db_name

-- ------------------------------------------------------------------- role

SELECT format('CREATE ROLE %I LOGIN PASSWORD %L', :'app_user', :'app_password')
WHERE NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = :'app_user')
\gexec

SELECT format('ALTER ROLE %I WITH LOGIN PASSWORD %L', :'app_user', :'app_password')
\gexec

\if :{?developer}
    SELECT format('ALTER ROLE %I CREATEDB', :'app_user')
    \gexec
\endif

-- --------------------------------------------------------------- database

SELECT format('CREATE DATABASE %I OWNER %I ENCODING ''UTF8'' TEMPLATE template0',
              :'db_name', :'app_user')
WHERE NOT EXISTS (SELECT 1 FROM pg_database WHERE datname = :'db_name')
\gexec

-- Ownership, in case the database existed already under someone else.
SELECT format('ALTER DATABASE %I OWNER TO %I', :'db_name', :'app_user')
\gexec

SELECT format('GRANT ALL PRIVILEGES ON DATABASE %I TO %I', :'db_name', :'app_user')
\gexec

-- Nobody else may connect. (PostgreSQL grants CONNECT to PUBLIC by default.)
SELECT format('REVOKE CONNECT ON DATABASE %I FROM PUBLIC', :'db_name')
\gexec

-- ----------------------------------------------------------------- schema

\connect :db_name

-- Every SivaComm table lives in schema comm. Created here, owned by the
-- application role, so the migrations can create tables in it.
SELECT format('CREATE SCHEMA IF NOT EXISTS comm AUTHORIZATION %I', :'app_user')
\gexec

SELECT format('ALTER SCHEMA comm OWNER TO %I', :'app_user')
\gexec

SELECT format('GRANT ALL ON SCHEMA comm TO %I', :'app_user')
\gexec


-- ----------------------------------------- tables, as the application role

-- Owned by the application role, not postgres: its later migrations must be
-- able to alter them.
SET ROLE :"app_user";
CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    migration_id character varying(150) NOT NULL,
    product_version character varying(32) NOT NULL,
    CONSTRAINT pk___ef_migrations_history PRIMARY KEY (migration_id)
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
        IF NOT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname = 'comm') THEN
            CREATE SCHEMA comm;
        END IF;
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE TABLE comm.admin_users (
        id uuid NOT NULL,
        username character varying(60) NOT NULL,
        password_hash text NOT NULL,
        password_salt text NOT NULL,
        is_active boolean NOT NULL,
        created_at timestamp with time zone NOT NULL,
        last_login_at timestamp with time zone,
        CONSTRAINT pk_admin_users PRIMARY KEY (id)
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE TABLE comm.applications (
        id uuid NOT NULL,
        code character varying(40) NOT NULL,
        name character varying(120) NOT NULL,
        is_active boolean NOT NULL,
        created_at timestamp with time zone NOT NULL,
        CONSTRAINT pk_applications PRIMARY KEY (id),
        CONSTRAINT ck_applications_code CHECK (code ~ '^[a-z0-9][a-z0-9-]{1,39}$')
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE TABLE comm.audit_events (
        id bigint GENERATED BY DEFAULT AS IDENTITY,
        application_id uuid,
        event_type character varying(40) NOT NULL,
        challenge_id uuid,
        message_id uuid,
        correlation_id character varying(64),
        detail character varying(300),
        created_at timestamp with time zone NOT NULL,
        CONSTRAINT pk_audit_events PRIMARY KEY (id)
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE TABLE comm.message_events (
        id uuid NOT NULL,
        message_id uuid,
        event_key character varying(240) NOT NULL,
        provider_message_id character varying(200) NOT NULL,
        status character varying(16) NOT NULL,
        occurred_at timestamp with time zone NOT NULL,
        received_at timestamp with time zone NOT NULL,
        error_code character varying(40),
        applied boolean NOT NULL,
        CONSTRAINT pk_message_events PRIMARY KEY (id)
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE TABLE comm.request_nonces (
        application_id uuid NOT NULL,
        nonce character varying(64) NOT NULL,
        created_at timestamp with time zone NOT NULL,
        CONSTRAINT pk_request_nonces PRIMARY KEY (application_id, nonce)
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE TABLE comm.application_keys (
        id uuid NOT NULL,
        application_id uuid NOT NULL,
        key_id character varying(40) NOT NULL,
        secret_encrypted bytea NOT NULL,
        created_at timestamp with time zone NOT NULL,
        revoked_at timestamp with time zone,
        last_used_at timestamp with time zone,
        CONSTRAINT pk_application_keys PRIMARY KEY (id),
        CONSTRAINT fk_application_keys_applications_application_id FOREIGN KEY (application_id) REFERENCES comm.applications (id) ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE TABLE comm.application_templates (
        id uuid NOT NULL,
        application_id uuid NOT NULL,
        purpose character varying(24) NOT NULL,
        template_name character varying(512) NOT NULL,
        language_code character varying(16) NOT NULL,
        parameter_count integer NOT NULL,
        CONSTRAINT pk_application_templates PRIMARY KEY (id),
        CONSTRAINT ck_application_templates_params CHECK (parameter_count BETWEEN 0 AND 10),
        CONSTRAINT fk_application_templates_applications_application_id FOREIGN KEY (application_id) REFERENCES comm.applications (id) ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE TABLE comm.messages (
        id uuid NOT NULL,
        application_id uuid NOT NULL,
        challenge_id uuid,
        purpose character varying(24) NOT NULL,
        channel character varying(16) NOT NULL,
        client_reference character varying(100),
        template_name character varying(512) NOT NULL,
        language_code character varying(16) NOT NULL,
        recipient_encrypted bytea,
        recipient_masked character varying(24) NOT NULL,
        payload_encrypted bytea,
        status character varying(16) NOT NULL,
        attempts integer NOT NULL,
        next_attempt_at timestamp with time zone NOT NULL,
        locked_until timestamp with time zone,
        provider_message_id character varying(200),
        last_error character varying(300),
        created_at timestamp with time zone NOT NULL,
        updated_at timestamp with time zone NOT NULL,
        submitted_at timestamp with time zone,
        sent_at timestamp with time zone,
        delivered_at timestamp with time zone,
        read_at timestamp with time zone,
        failed_at timestamp with time zone,
        CONSTRAINT pk_messages PRIMARY KEY (id),
        CONSTRAINT fk_messages_applications_application_id FOREIGN KEY (application_id) REFERENCES comm.applications (id) ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE TABLE comm.otp_challenges (
        id uuid NOT NULL,
        application_id uuid NOT NULL,
        reset_reference character varying(100) NOT NULL,
        user_reference character varying(100) NOT NULL,
        purpose character varying(24) NOT NULL,
        otp_hmac bytea NOT NULL,
        recipient_masked character varying(24) NOT NULL,
        status character varying(24) NOT NULL,
        attempts integer NOT NULL,
        max_attempts integer NOT NULL,
        send_count integer NOT NULL,
        last_sent_at timestamp with time zone NOT NULL,
        expires_at timestamp with time zone NOT NULL,
        verified_at timestamp with time zone,
        completed_at timestamp with time zone,
        created_at timestamp with time zone NOT NULL,
        CONSTRAINT pk_otp_challenges PRIMARY KEY (id),
        CONSTRAINT ck_otp_challenges_attempts CHECK (attempts >= 0 AND attempts <= max_attempts),
        CONSTRAINT ck_otp_challenges_sends CHECK (send_count >= 1),
        CONSTRAINT fk_otp_challenges_applications_application_id FOREIGN KEY (application_id) REFERENCES comm.applications (id) ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE TABLE comm.verification_grants (
        id uuid NOT NULL,
        challenge_id uuid NOT NULL,
        grant_hash bytea NOT NULL,
        expires_at timestamp with time zone NOT NULL,
        consumed_at timestamp with time zone,
        consume_key character varying(100),
        created_at timestamp with time zone NOT NULL,
        CONSTRAINT pk_verification_grants PRIMARY KEY (id),
        CONSTRAINT fk_verification_grants_otp_challenges_challenge_id FOREIGN KEY (challenge_id) REFERENCES comm.otp_challenges (id) ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE UNIQUE INDEX ix_admin_users_username ON comm.admin_users (username);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE UNIQUE INDEX ix_application_keys_application_id_key_id ON comm.application_keys (application_id, key_id);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE UNIQUE INDEX ix_application_templates_application_id_purpose ON comm.application_templates (application_id, purpose);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE UNIQUE INDEX ix_applications_code ON comm.applications (code);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE INDEX ix_audit_events_application_id_created_at ON comm.audit_events (application_id, created_at);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE INDEX ix_audit_events_event_type_created_at ON comm.audit_events (event_type, created_at);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE UNIQUE INDEX ix_message_events_event_key ON comm.message_events (event_key);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE INDEX ix_message_events_unapplied ON comm.message_events (provider_message_id) WHERE NOT applied;
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE UNIQUE INDEX ix_messages_application_id_client_reference ON comm.messages (application_id, client_reference) WHERE client_reference IS NOT NULL;
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE INDEX ix_messages_application_id_created_at ON comm.messages (application_id, created_at);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE INDEX ix_messages_challenge_id ON comm.messages (challenge_id);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE INDEX ix_messages_created_at ON comm.messages (created_at);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE UNIQUE INDEX ix_messages_provider_message_id ON comm.messages (provider_message_id) WHERE provider_message_id IS NOT NULL;
    END IF;
