DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE INDEX ix_messages_queue ON comm.messages (next_attempt_at) WHERE status = 'Queued';
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE UNIQUE INDEX ix_otp_challenges_application_id_reset_reference ON comm.otp_challenges (application_id, reset_reference);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE INDEX ix_otp_challenges_application_id_user_reference_created_at ON comm.otp_challenges (application_id, user_reference, created_at);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE INDEX ix_otp_challenges_created_at ON comm.otp_challenges (created_at);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE INDEX ix_request_nonces_created_at ON comm.request_nonces (created_at);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE UNIQUE INDEX ix_verification_grants_challenge_id ON comm.verification_grants (challenge_id);
    END IF;
