DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    CREATE UNIQUE INDEX ix_verification_grants_grant_hash ON comm.verification_grants (grant_hash);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261024155431_Initial') THEN
    INSERT INTO "__EFMigrationsHistory" (migration_id, product_version)
    VALUES ('20261024155431_Initial', '10.0.11');
    END IF;
END $EF$;
COMMIT;


RESET ROLE;
\echo
\echo Applied migrations:
SELECT migration_id FROM public."__EFMigrationsHistory" ORDER BY 1;
\echo Tables in schema comm, and who owns them:
SELECT count(*) AS tables, tableowner FROM pg_tables WHERE schemaname = 'comm' GROUP BY tableowner;
\echo Done. Set Database:Password in appsettings.Production.json and run Install-SivaComm.ps1.